// StructToAvro converts a Go struct into an Avro schema.
func StructToAvro(fileName string) error {
	// Read the contents of the file
	fileContent, err := ioutil.ReadFile(fileName)
	if err != nil {
		return fmt.Errorf("reading file: %w", err)
	}

	// Parse the YAML content
	var data map[string]interface{}
	err = yaml.Unmarshal(fileContent, &data)
	if err != nil {
		return fmt.Errorf("unmarshalling YAML: %w", err)
	}

	// Get the struct type from the parsed data
	structType, ok := data["struct"]
	if !ok {
		return fmt.Errorf("no 'struct' field found")
	}
	structName, ok := structType.(string)
	if !ok {
		return fmt.Errorf("'struct' field must be a string")
	}

	// Convert the struct to JSON
	jsonBytes, err := json.MarshalIndent(data, "", "    ")
	if err != nil {
		return fmt.Errorf("serializing struct: %w", err)
	}

	// Parse the JSON as a Go slice (assuming all fields are maps or slices)
	slice, err := jsonpb.Parse(jsonBytes)
	if err != nil {
		return fmt.Errorf("parsing JSON: %w", err)
	}

	// Create a schema based on the first element of the slice
	fieldDefs := make([]jsonpb.FieldDef, 0, len(slice[0].Fields))
	for _, field := range slice[0].Fields {
		fieldDef := jsonpb.FieldDef{
			Name: field.Name,
			Type: field.Type.String(),
		}
		fieldDefs = append(fieldDefs, fieldDef)
	}
	schema := jsonpb.Schema{
		Fields: fieldDefs,
	}

	// Write the generated schema to a file
	outFile, err := os.Create(fmt.Sprintf("%s.avsc", structName))
	if err != nil {
		return fmt.Errorf("creating output file: %w", err)
	}
	defer outFile.Close()

	encoder := json.NewEncoder(outFile)
	if err := encoder.Encode(schema); err != nil {
		return fmt.Errorf("encoding schema: %w", err)
	}

	return nil
}

func main() {
	args := os.Args
	if len(args) < 3 {
		fmt.Println("Usage:", args[0], "<file-name> <struct-name>")
		os.Exit(1)
	}

	fileName := args[1]
	structName := args[2]

	err := StructToAvro(fileName)
	if err != nil {
		fmt.Printf("Error generating Avro schema: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("Generated Avro schema saved at %s.avsc\n", structName)
}
```

