```java
import org.audacity.core.Audacity;
import org.audacity.core.audio.AudioFile;
import org.audacity.core.audio.AudioTrack;
import java.io.File;

public class AudioMixer {
    public static void main(String[] args) throws Exception {
        // Load the first audio file
        File file1 = new File("path/to/file1.wav");
        AudioFile af1 = new AudioFile(file1);
        AudioTrack track1 = af1.getTrack(0);

        // Load the second audio file
        File file2 = new File("path/to/file2.wav");
        AudioFile af2 = new AudioFile(file2);
        AudioTrack track2 = af2.getTrack(0);

        // Mix the two audio tracks together
        double[][] mixedData = new double[track1.getNumSamples()][];
        for (int i = 0; i < track1.getNumSamples(); i++) {
            double[] sample1 = track1.sample(i);
            double[] sample2 = track2.sample(i);
            for (int j = 0; j < sample1.length; j++) {
                mixedData[i][j] = sample1[j] * 0.5 + sample2[j] * 0.5;
            }
        }

        // Save the mixed audio as a new file
        AudioFile af3 = new AudioFile(new File("output/summer_day.wav"));
        af3.addAudioTrack(mixedData, 0);
        af3.save();
    }
